INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8ae8-7a2e-bc34-7472bf448a72'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'Express 840 as a product of prime factors.', '2^3 × 3 × 5 × 7', '840 = 84 × 10 = (2^2 × 3 × 7) × (2 × 5) = 2^3 × 3 × 5 × 7.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.264Z'::timestamptz, '2026-08-15T07:36:12.264Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8afc-7f0a-a5bd-9887c9c91c27'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'The least common multiple of 12, x and 28 is 420. Find two possible values of x between 12 and 100.', '15 and 35', '420 = 2^2 × 3 × 5 × 7. Since 12 = 2^2 × 3 and 28 = 2^2 × 7, x must contribute a factor of 5 without creating higher powers that change the LCM. Two possible values are 15 and 35.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.284Z'::timestamptz, '2026-08-15T07:36:12.284Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8b10-7d45-abfc-6e190508e230'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Jessica invests $4540 at a rate of r% per year compound interest. At the end of 10 years, she has earned $1328.54 in interest. Find the value of r.', '2.5%', 'Final amount = 4540 + 1328.54 = 5868.54. So 4540(1 + r/100)^10 = 5868.54. Divide by 4540 to get (1 + r/100)^10 = 1.292. Taking the 10th root gives 1 + r/100 ≈ 1.025. Therefore r = 2.5%.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.304Z'::timestamptz, '2026-08-15T07:36:12.304Z'::timestamptz) ON CONFLICT (id) DO NOTHING;